// SAINTS KNOWLEDGE BASE — source of truth, edited in the repo.
//
// The Recollection app renders these READ-ONLY. Everything Mario personally
// records about a saint (relationship status, 0–5 familiarity per section,
// personal notes, flashcard progress) lives separately in the store
// (localStorage now, Drive later), keyed by `slug`. Same one-way flow as
// wardrobe/data/wardrobe.yaml → the wardrobe HTML views.
//
// `depth: "full"`  — the complete dossier, all 11 sections.
// `depth: "core"`  — scaffold: identity, dates, order, one-line charism,
//                    patronages, a couple of flashcards. Enough for the
//                    calendar export and for the saint to be findable;
//                    deepened in later passes.
//
// Anecdotes carry `legend: true` when the story is traditional/pious rather
// than documented — the app shows that distinction rather than hiding it.
//
// Feast days are MM-DD strings on the current General Roman Calendar unless
// noted; `altFeasts` carries pre-1969, Eastern, national and order calendars.

// Compact constructor for the scaffold records. Produces exactly the same
// shape as a full dossier — just with most fields left empty — so the app
// never needs to know which kind it is rendering. Deepening a saint means
// replacing its core({...}) call with a full literal like the six below.
function core(o) {
  return {
    slug: o.slug,
    name: o.name,
    sortName: o.sortName || o.name.replace(/^(St\.|Ss\.) /, ""),
    depth: "core",
    listTier: o.listTier || "",
    // Where someone stands in the canonization process: "servant" (Servant
    // of God) → "venerable" → "blessed" → "saint". Defaults to "saint"
    // since that's true of everyone in this file except the handful of
    // open causes added deliberately (e.g. Fulton Sheen, Clare Crockett).
    causeStage: o.causeStage || "saint",
    identity: {
      birthName: o.birthName || "",
      religiousName: o.religiousName || "",
      originalName: o.originalName || "",
      epithets: o.epithets || [],
      titles: o.titles || [],
      doctorTitle: o.doctorTitle || "",
      doctorDeclared: o.doctorDeclared || "",
      rank: o.rank || "",
    },
    dates: {
      feast: o.feast,
      feastLabel: o.feastLabel,
      altFeasts: o.altFeasts || [],
      born: o.born || "",
      bornPlace: o.bornPlace || "",
      died: o.died || "",
      diedPlace: o.diedPlace || "",
      deathManner: o.deathManner || "",
      ageAtDeath: o.ageAtDeath || "",
      beatified: o.beatified || null,
      canonized: o.canonized || null,
      landmarks: [],
    },
    life: {
      nationality: o.nationality || "",
      era: o.era || "",
      order: o.order || "",
      stateOfLife: o.state || "",
      family: o.family || "",
      places: [],
      offices: [],
    },
    narrative: {
      summary: o.summary || "",
      story: "",
      timeline: [],
      anecdotes: o.anecdotes || [],
      phenomena: o.phenomena || [],
      sufferings: "",
      death: "",
      lastWords: o.lastWords || "",
    },
    spirituality: {
      charism: o.charism || "",
      teachings: o.teachings || [],
      devotions: [],
      school: o.school || "",
      influencedBy: [],
      influenced: [],
    },
    // The concrete, repeatable daily/weekly rhythm of practices the saint
    // actually kept — distinct from `spirituality` (their teaching/approach)
    // and from `narrative` (their life story). `forYou` translates it for a
    // modern lay reader who isn't cloistered.
    dailyPractice: {
      rhythm: o.dailyRhythm || "",
      practices: o.dailyPractices || [],
      forYou: o.dailyForYou || "",
    },
    writings: o.writings || [],
    writingsNotes: o.writingsNotes || "",
    about: o.about || {},
    cult: {
      patronages: o.patronages || [],
      invokedAgainst: o.invokedAgainst || [],
      attributes: o.attributes || [],
      relics: o.relics || "",
      incorrupt: !!o.incorrupt,
      shrines: o.shrines || [],
      devotions: o.cultDevotions || [],
      foundations: o.foundations || [],
    },
    connections: { related: o.related || [] },
    cards: o.cards || [],
    note: o.note || "",
  };
}

